{"task": "Find all log messages that contain a US-style phone number", "sql": "SELECT ts, level, service, message FROM logs WHERE regexp_like(message, '\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}')"}
{"task": "Count how many log messages per service contain a phone number", "sql": "SELECT service, COUNT(*) AS phone_count FROM logs WHERE regexp_like(message, '\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}') GROUP BY service ORDER BY phone_count DESC"}
{"task": "Flag each log message with whether it contains a phone number using a CASE expression", "sql": "SELECT ts, service, message, CASE WHEN regexp_like(message, '\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}') THEN 'HAS_PHONE' ELSE 'NO_PHONE' END AS phone_flag FROM logs"}
{"task": "Find error-level log messages containing a phone number in international format with a leading plus sign", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, '\\+\\d{1,3}[-. ]?\\d{2,4}[-. ]?\\d{3}[-. ]?\\d{4}')"}
{"task": "List distinct services that have ever logged a message containing a phone number", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, '\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}')"}
{"task": "Find log messages with phone numbers logged within the last 24 hours ordered by newest first", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}') AND ts >= NOW() - INTERVAL '24 hours' ORDER BY ts DESC"}
{"task": "Join logs containing phone numbers with events sharing the same approximate timestamp to see related request paths", "sql": "SELECT l.ts, l.service, l.message, e.path, e.status FROM logs l JOIN events e ON e.id BETWEEN 1 AND 1000000 WHERE regexp_like(l.message, '\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}') AND regexp_like(e.path, 'phone=\\d{3,}')"}
{"task": "Detect log messages matching both a phone number pattern and the word 'support' case-insensitively", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}') AND regexp_like(message, 'support', 'i')"}
{"task": "Compute the percentage of log messages per day that contain a phone number to monitor potential PII leakage", "sql": "SELECT CAST(ts AS DATE) AS log_date, SUM(CASE WHEN regexp_like(message, '\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}') THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS pct_with_phone FROM logs GROUP BY CAST(ts AS DATE) ORDER BY log_date"}
{"task": "Find event request paths with a phone query-string parameter and correlate with matching log messages containing the same digit pattern length", "sql": "SELECT e.path, l.message FROM events e JOIN logs l ON regexp_like(e.path, 'phone=\\d{10}') WHERE regexp_like(l.message, '\\(?\\d{3}\\)?[-. ]?\\d{3}[-. ]?\\d{4}') LIMIT 100"}

